create or replace function public.accept_pilot_invitation(
  invite_token text,
  consent_acknowledged boolean,
  consent_version text
)
returns table (workplace_id uuid, workplace_name text, member_role text)
language plpgsql
security definer
set search_path = public, auth, extensions, pg_temp
as $$
declare
  current_profile_id uuid := auth.uid();
  current_email text := lower(trim(coalesce(auth.jwt() ->> 'email', '')));
  normalized_token text := trim(coalesce(invite_token, ''));
  invitation public.pilot_invitations%rowtype;
begin
  if current_profile_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if consent_acknowledged is distinct from true or consent_version is distinct from 'pilot-privacy-v1' then
    raise exception 'Pilot consent acknowledgment required' using errcode = '22023';
  end if;
  select * into invitation from public.pilot_invitations
  where token_hash = encode(
    extensions.digest(convert_to(normalized_token, 'UTF8'), 'sha256'), 'hex'
  ) for update;
  if invitation.id is null
    or invitation.volunteer_confirmed_at is null
    or invitation.accepted_at is not null
    or invitation.revoked_at is not null
    or invitation.expires_at <= now() then
    raise exception 'Invitation is not available' using errcode = '22023';
  end if;
  if current_email = '' or current_email <> invitation.email then
    raise exception 'Invitation email does not match' using errcode = '42501';
  end if;
  if lower(invitation.role) = 'manager' and invitation.invited_by is not null then
    raise exception 'Manager invitations require service authorization' using errcode = '42501';
  end if;
  if exists (
    select 1 from public.workplace_members as membership
    where membership.profile_id = current_profile_id
      and membership.membership_status = 'active'
  ) then
    raise exception 'Account already has an active workplace membership' using errcode = '23505';
  end if;

  insert into public.workplace_members (
    workplace_id, profile_id, role, membership_status, joined_at,
    pilot_consented_at, pilot_consent_version
  ) values (
    invitation.workplace_id, current_profile_id, invitation.role, 'active', now(),
    now(), consent_version
  )
  on conflict on constraint workplace_members_pkey do update set
    role = excluded.role,
    membership_status = 'active',
    joined_at = excluded.joined_at,
    deactivated_at = null,
    deactivated_by = null,
    deactivation_reason = null,
    pilot_consented_at = excluded.pilot_consented_at,
    pilot_consent_version = excluded.pilot_consent_version;

  update public.pilot_invitations
  set accepted_at = now(), accepted_profile_id = current_profile_id
  where id = invitation.id;

  return query select workplace.id, workplace.name, invitation.role
  from public.workplaces as workplace where workplace.id = invitation.workplace_id;
end;
$$;
-- Consent CHECK deliberately unchanged.
CREATE OR REPLACE FUNCTION public.is_active_workplace_member(
 target_workplace_id uuid,target_profile_id uuid DEFAULT auth.uid()
) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER
SET search_path=public,pg_temp AS $$
 SELECT (
  EXISTS (SELECT 1 FROM public.workplace_members caller_membership
    WHERE caller_membership.workplace_id=target_workplace_id
      AND caller_membership.profile_id=auth.uid()
      AND caller_membership.membership_status='active')
 ) AND EXISTS (
  SELECT 1 FROM public.workplace_members membership
  WHERE membership.workplace_id=target_workplace_id
    AND membership.profile_id=target_profile_id
    AND membership.membership_status='active'
 );
$$;
REVOKE ALL ON FUNCTION public.is_active_workplace_member(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.is_active_workplace_member(uuid,uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.is_active_workplace_member(uuid,uuid) FROM service_role;

CREATE FUNCTION public.enforce_shift_creator_attribution()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path=public,auth,pg_temp AS $$
BEGIN
 -- SECURITY DEFINER is needed for an existence check unaffected by caller RLS.
 -- Accept only an FK-compatible NULL when the actual old profile is gone;
 -- never treat lack of caller visibility as proof of deletion.
 IF TG_OP='UPDATE' AND old.manager_profile_id IS NOT NULL
    AND new.manager_profile_id IS NULL
    AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=old.manager_profile_id)
 THEN RETURN new; END IF;
 -- No-user administrator maintenance only; no service exception.
 IF auth.uid() IS NULL AND session_user IN ('postgres','supabase_admin')
    AND current_setting('role') IN ('none','postgres','supabase_admin')
 THEN RETURN new; END IF;
 IF TG_OP='INSERT' THEN
  IF auth.uid() IS NULL THEN
   RAISE EXCEPTION 'Authenticated creator required' USING ERRCODE='42501';
  END IF;
  new.manager_profile_id:=auth.uid();
 ELSIF new.manager_profile_id IS DISTINCT FROM old.manager_profile_id THEN
  RAISE EXCEPTION 'Shift creator attribution is immutable' USING ERRCODE='42501';
 END IF;
 RETURN new;
END;
$$;
REVOKE ALL ON FUNCTION public.enforce_shift_creator_attribution() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER enforce_shift_creator_attribution
BEFORE INSERT OR UPDATE ON public.shifts
FOR EACH ROW EXECUTE FUNCTION public.enforce_shift_creator_attribution();

-- Browser maintenance privileges only; preserve CRUD and service_role.
REVOKE TRUNCATE,TRIGGER,REFERENCES,MAINTAIN ON TABLE public."coverage_events" FROM "authenticated";
REVOKE TRUNCATE,TRIGGER,REFERENCES,MAINTAIN ON TABLE public."direct_shift_offers" FROM "anon";
REVOKE TRUNCATE,TRIGGER,REFERENCES,MAINTAIN ON TABLE public."direct_shift_offers" FROM "authenticated";
REVOKE TRUNCATE,TRIGGER,REFERENCES,MAINTAIN ON TABLE public."profiles" FROM "anon";
REVOKE TRUNCATE,TRIGGER,REFERENCES,MAINTAIN ON TABLE public."profiles" FROM "authenticated";
REVOKE TRUNCATE,TRIGGER,REFERENCES,MAINTAIN ON TABLE public."shift_interests" FROM "authenticated";
REVOKE TRUNCATE,TRIGGER,REFERENCES,MAINTAIN ON TABLE public."shifts" FROM "anon";
REVOKE TRUNCATE,TRIGGER,REFERENCES,MAINTAIN ON TABLE public."shifts" FROM "authenticated";
REVOKE TRUNCATE,TRIGGER,REFERENCES,MAINTAIN ON TABLE public."workplace_members" FROM "anon";
REVOKE TRUNCATE,TRIGGER,REFERENCES,MAINTAIN ON TABLE public."workplace_members" FROM "authenticated";
REVOKE TRUNCATE,TRIGGER,REFERENCES,MAINTAIN ON TABLE public."workplaces" FROM "anon";
REVOKE TRUNCATE,TRIGGER,REFERENCES,MAINTAIN ON TABLE public."workplaces" FROM "authenticated";
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public REVOKE TRUNCATE,TRIGGER,REFERENCES,MAINTAIN ON TABLES FROM anon,authenticated;

