oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal ORDER BY 1,2) q)) v WHERE v->>'relation'='shifts' AND v->>'name'='enforce_shift_creator_attribution'),'constraints',(SELECT coalesce(jsonb_agg(v ORDER BY v::text),'[]'::jsonb) FROM jsonb_array_elements((SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text),'[]'::jsonb) FROM (SELECT c.relname AS relation,con.conname AS name,con.contype AS kind,con.convalidated AS validated,pg_get_constraintdef(con.oid) AS definition FROM pg_constraint con JOIN pg_class c ON c.oid=con.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' ORDER BY 1,2) q)) v WHERE v->>'relation'='shifts' AND v->>'name'='shifts_manager_profile_id_fkey'),'default_acls',(SELECT coalesce(jsonb_agg(v ORDER BY v::text),'[]'::jsonb) FROM jsonb_array_elements((SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text),'[]'::jsonb) FROM (SELECT pg_get_userbyid(d.defaclrole) AS owner,coalesce(n.nspname,'(global)') AS schema,d.defaclobjtype AS kind,ARRAY(SELECT a::text FROM unnest(d.defaclacl) a ORDER BY a::text)::text AS acl FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE d.defaclnamespace=0 OR n.nspname='public' ORDER BY 1,2,3) q)) v WHERE v->>'owner'='postgres' AND v->>'kind'='r'));
IF NOT (((s->'functions') @> (expected->'functions') AND (expected->'functions') @> (s->'functions') AND jsonb_array_length(s->'functions')=jsonb_array_length(expected->'functions')) AND ((s->'relations') @> (expected->'relations') AND (expected->'relations') @> (s->'relations') AND jsonb_array_length(s->'relations')=jsonb_array_length(expected->'relations')) AND ((s->'triggers') @> (expected->'triggers') AND (expected->'triggers') @> (s->'triggers') AND jsonb_array_length(s->'triggers')=jsonb_array_length(expected->'triggers')) AND ((s->'constraints') @> (expected->'constraints') AND (expected->'constraints') @> (s->'constraints') AND jsonb_array_length(s->'constraints')=jsonb_array_length(expected->'constraints')) AND ((s->'default_acls') @> (expected->'default_acls') AND (expected->'default_acls') @> (s->'default_acls') AND jsonb_array_length(s->'default_acls')=jsonb_array_length(expected->'default_acls'))) THEN RAISE EXCEPTION 'STOP: security reconciliation postcondition mismatch'; END IF;
